  "Caller ID by Google": {"res": "GoogleDialer:google_caller_id_setting_title", "hu": "Google általi hívásazonosítás", "de": "Anrufer-ID von Google", "fr": "Identification de l'appelant par Google", "es": "ID de llamada de Google"},
  "Show names for people and businesses not in your contacts.": {"res": "GoogleDialer:google_caller_id_setting__on", "hu": "A névjegyekben nem szereplő személyek/cégek nevének mutatása", "de": "Namen von Personen und Unternehmen anzeigen, die nicht in meinen Kontakten sind", "fr": "Afficher les noms des personnes et des entreprises qui ne figurent pas dans vos contacts", "es": "Mostrar los nombres de personas y empresas que no estén en tus contactos"},
  "caller-id-text": {"res": "GoogleDialer:google_caller_id_settings_text", "hu": "<a href=%1$s>A Google\n        általi hívásazonosítás</a> megjeleníti a névjegyekben nem szereplő személyek és cégek nevét.\n        <br><br>\n        Frissítse telefonszáma felfedezhetőségét\n        <a href=%2$s>Google-fiókjának beállításaiban</a>.\n        <br><br>\n        Az ezen funkciókban használt adatokat a Google és licencadói szolgáltatják.\n        <a href=%3$s>További információ.</a>", "de": "<a href=%1$s>Anrufer-ID\n        von Google</a> zeigt Namen von Personen und Unternehmen an, die nicht in Ihren Kontakten sind.\n        <br><br>\n        Sie können die Sichtbarkeit Ihrer Telefonnummer in Ihren\n        <a href=%2$s>Google-Kontoeinstellungen</a> aktualisieren.\n        <br><br>\n        Die in diesen Funktionen verwendeten Daten werden von Google und seinen Lizenzgebern bereitgestellt.\n        <a href=%3$s>Weitere Informationen</a>", "fr": "Le service <a href=%1$s>Identification\n        de l'appelant par Google</a> affiche les noms des personnes et des entreprises qui ne figurent pas dans vos contacts.\n        <br><br>\n        Mettez à jour la visibilité de votre numéro de téléphone dans les\n        <a href=%2$s>paramètres de votre compte Google</a>.\n        <br><br>\n        Les données utilisées par ces fonctionnalités sont fournies par Google et ses concédants.\n        <a href=%3$s>En savoir plus</a>", "es": "El <a href=%1$s>ID de llamada\n de Google</a> muestra los nombres de las personas y las empresas que no están en tu lista de contactos.\n        <br><br>\n Cambia la visibilidad de tu número de teléfono para otras personas en los\n <a href=%2$s>ajustes de tu cuenta de Google</a>.\n <br><br>\n Google y sus proveedores de licencias son los encargados de proporcionar los datos que se utilizan en estas funciones.\n <a href=%3$s>Más información</a>", "en": "<a href=%1$s>Caller ID by Google</a> shows names for people and businesses not in your contacts. <br><br> Update the discoverability of your phone number in your <a href=%2$s>Google account settings</a>. <br><br> Data being used in these features is provided by Google and its licensors. <a href=%3$s>Learn more.</a>"},
  "Nearby places": {"res": "GoogleDialer:local_search_setting_title", "hu": "Közeli helyek", "de": "Orte in der Nähe", "fr": "Adresses à proximité", "es": "Sitios cercanos"},
  "Display search results for nearby places": {"res": "GoogleDialer:local_search_setting_on", "hu": "A közeli helyek találatainak megjelenítése", "de": "Suchergebnisse für Orte in der Nähe anzeigen", "fr": "Afficher les adresses à proximité dans les résultats de recherche", "es": "Mostrar resultados de búsqueda de sitios cercanos"},
  "nearby-text": {"res": "GoogleDialer:local_search_settings_text", "hu": "Amikor a telefonos alkalmazásban végez keresést, ez a funkció a helyadatokat használja, hogy a keresésnek megfelelő közeli helyeket találjon, még akkor is, ha azok nem szerepelnek a névjegyek között. <br><br> Az ezen funkcióknál használt adatokat a Google és licencadói szolgáltatják. <a href=%1$s>További információ</a>\n        <br><br>\n        A funkció használatához engedélyezze a Google-alkalmazások számára a telefon helyadatainak használatát.\n        <a href=%2$s>További információ</a>", "de": "Bei einer Suche mit der Telefon-App nutzt diese Funktion Ihren Standort, um Orte in der Nähe zu suchen, die mit Ihrer Suchanfrage übereinstimmen, auch wenn diese nicht in Ihren Kontakten sind. <br><br> In diesen Funktionen verwendete Daten werden von Google und seinen Lizenzgebern bereitgestellt. <a href=%1$s>Weitere Informationen</a>\n        <br><br>\n        Um diese Funktion zu nutzen, gestatten Sie Google-Apps, den Standort Ihres Telefons zu verwenden.\n        <a href=%2$s>Weitere Informationen</a>", "fr": "Lorsque vous effectuez des recherches à partir de l'application Téléphone, vos données de localisation sont utilisées pour trouver des adresses à proximité qui correspondent à votre requête de recherche, même si elles ne figurent pas dans vos contacts. <br><br> Les données de ces fonctionnalités sont fournies par Google et ses concédants. <a href=%1$s>En savoir plus</a>\n        <br><br>\n        Pour profiter de cette fonctionnalité, autorisez les applications Google à utiliser la position de votre téléphone.\n        <a href=%2$s>En savoir plus</a>", "es": "Al hacer búsquedas en el teléfono, esta función utilizará tu ubicación para encontrar sitios cercanos que coincidan con tu consulta aunque la información no esté en tu lista de contactos. <br><br> Google y sus proveedores de licencias son los encargados de proporcionar los datos que se utilizan en estas funciones. <a href=%1$s>Más información</a>\n        <br><br>\n        Debes permitir que las aplicaciones de Google utilicen la ubicación del teléfono para que este servicio funcione correctamente.\n        <a href=%2$s>Más información</a>", "en": "When you search from the phone app, this feature will use your location to find nearby places that match your query, even if they are not in your contacts. <br><br> Data being used in these features is provided by Google and its licensors. <a href=%1$s>Learn more</a> <br><br> To use this feature, allow Google apps to use your phone's location. <a href=%2$s>Learn more</a>"},
  "Go to location settings": {"res": "GoogleDialer:view_location_settings", "hu": "Ugrás a helybeállításokhoz", "de": "Zu den Standorteinstellungen", "fr": "Paramètres de localisation", "es": "Ir a ajustes de ubicación"},
