  "Android Device Manager": {"res": "PrebuiltGmsCore:common_mdm_feature_name", "hu": "Android Eszközkezelő", "de": "Android Geräte-Manager", "fr": "Gestionnaire d'appareils Android", "es": "Administrador de dispositivos"},
