  "Locate disabled summary": {"res": "PrebuiltGmsCore:mdm_settings_locate_disabled_summary", "hu": "Nem érhető el, mert a Google Beállítások > Hely > Tartózkodási hely elérése ki van kapcsolva", "de": "Nicht verfügbar, weil unter \"Google-Einstellungen\" > \"Standort\" die Option \"Standortzugriff\" deaktiviert ist", "fr": "Indisponible, car l'option \"Accéder aux données de localisation\" sous Paramètres Google > Position est désactivée.", "es": "No disponible porque la opción Ajustes de Google > Ubicación > Acceder a la ubicación está desactivada", "en": "Unavailable because Google Settings > Location > Access location is turned off"},
  "Allow remote lock and erase": {"res": "PrebuiltGmsCore:mdm_settings_wipe_title", "hu": "Távoli zárolás és törlés engedélyezése", "de": "Remote-Sperre und Löschen zulassen", "fr": "Autoriser verrouillage et suppression des données à distance", "es": "Permitir borrado y bloqueo remotos"},
  "Wipe summary": {"res": "PrebuiltGmsCore:mdm_settings_wipe_summary", "hu": "Ha elveszíti eszközét, az Android Eszközkezelővel távolról zárolhatja azt, illetve visszaállíthatja rajta a gyári beállításokat.", "de": "Wenn Sie Ihr Gerät verlieren, können Sie es mit dem Android Geräte-Manager per Remote-Zugriff sperren oder auf die Werkseinstellungen zurücksetzen.", "fr": "Si vous égarez votre appareil, vous pouvez le verrouiller ou le réinitialiser à distance grâce au Gestionnaire d'appareils Android.", "es": "Si pierdes tu dispositivo, puedes bloquearlo o restablecer los datos de fábrica de forma remota con el Administrador de dispositivos Android", "en": "If you lose your device, you can remotely lock or factory reset it with Android Device Manager"},
  "Verify apps": {"res": "PrebuiltGmsCore:verify_apps_section_title", "hu": "Alkalmazások ellenőrzése", "de": "Apps überprüfen", "fr": "Valider les applications", "es": "Verificar aplicaciones"},
  "Scan device for security threats": {"res": "PrebuiltGmsCore:verify_apps_title", "hu": "Ellenőrzés biztonsági veszélyek szempontjából", "de": "Gerät nach Sicherheitsbedrohungen durchsuchen", "fr": "Analyser appareil pour détecter menaces de sécurité", "es": "Buscar amenazas de seguridad en el dispositivo"},
  "Scan summary": {"res": "PrebuiltGmsCore:verify_apps_summary", "hu": "Eszköztevékenység rendszeres ellenőrzése és a potenciális veszélyek megelőzése, illetve értesítés küldése ezekről", "de": "Geräteaktivität regelmäßig überprüfen und vor potenziellen Schäden warnen oder diese verhindern", "fr": "Vérifier régulièrement l'activité de l'appareil pour empêcher tout dommage ou vous en avertir", "es": "Comprobar de forma regular la actividad del dispositivo y avisar sobre posibles daños y evitarlos", "en": "Regularly check device activity and prevent or warn about potential harm"},
