  "Confirm device credential deletion": {"res": "Chrome:protected_content_prefs_reset_title", "hu": "Az eszközhitelesítési adatok törlésének megerősítése", "de": "Löschen der Anmeldedaten des Geräts bestätigen", "fr": "Confirmer la suppression du certificat de l'appareil", "es": "Confirmar eliminación de credencial de dispositivo"},
