  "cp.Add events from Gmail": {"res": "CalendarGooglePrebuilt:add_automatically", "hu": "Események hozzáadása a Gmailből", "de": "Termine aus Gmail hinzufügen", "fr": "Importer des événements de Gmail", "es": "Añadir eventos de Gmail", "en": "Add events from Gmail"},
  "cp.Gmail on": {"res": "CalendarGooglePrebuilt:smartmail_toggle_on_dialog_text", "hu": "A rendszer automatikusan hozzáadja a Gmailben megjelenő jövőbeli eseményeket (például repülőjegy- vagy asztalfoglalásokat) a naptárhoz.", "de": "Zukünftige Termine wie Flugbuchungen und Restaurantreservierungen werden automatisch aus Gmail zu Ihrem Kalender hinzugefügt.", "fr": "Les événements futurs, comme les réservations de vol ou de restaurant, seront automatiquement ajoutés à votre agenda à partir de Gmail.", "es": "A partir de ahora, las reservas confirmadas (como billetes de avión o restaurantes) se añadirán automáticamente a tu calendario desde Gmail.", "en": "Future events like flight bookings and restaurant reservations will be automatically added to your calendar from Gmail."},
  "cp.Gmail off": {"res": "CalendarGooglePrebuilt:smartmail_toggle_off_dialog_text", "hu": "A rendszer a jövőben nem adja hozzá automatikusan az eseményeket az e-mailekből. A korábban a Gmailből hozzáadott eseményeket eltávolítja.", "de": "Termine werden nicht länger automatisch aus Ihren E-Mails in Ihren Kalender übertragen. Bereits aus Gmail hinzugefügte Termine werden wieder entfernt.", "fr": "Vous ne verrez plus les événements ajoutés automatiquement à partir de votre messagerie. Les événements ajoutés précédemment à partir de Gmail seront supprimés.", "es": "A partir de ahora no verás los eventos añadidos automáticamente desde tu correo electrónico. Además, se eliminarán los eventos anteriores añadidos desde Gmail.", "en": "You'll no longer see events automatically added from your email. Previously added events from Gmail will be removed."},
  "cp.Enable": {"res": "CalendarGooglePrebuilt:smartmail_toggle_on_dialog_confirm_button_text", "hu": "Engedélyezés", "de": "Aktivieren", "fr": "Activer", "es": "Habilitar", "en": "Enable"},
  "cp.Continue": {"res": "CalendarGooglePrebuilt:smartmail_toggle_off_dialog_confirm_button_text", "hu": "Folytatás", "de": "Weiter", "fr": "Continuer", "es": "Continuar", "en": "Continue"},
  "cp.week.0": {"res": "CalendarGooglePrebuilt:@array/preferences_week_start_day_labels:0", "hu": "szombat", "de": "Samstag", "fr": "samedi", "es": "Sábado", "en": "Saturday"},
  "cp.week.1": {"res": "CalendarGooglePrebuilt:@array/preferences_week_start_day_labels:1", "hu": "vasárnap", "de": "Sonntag", "fr": "dimanche", "es": "Domingo", "en": "Sunday"},
  "cp.week.2": {"res": "CalendarGooglePrebuilt:@array/preferences_week_start_day_labels:2", "hu": "hétfő", "de": "Montag", "fr": "lundi", "es": "Lunes", "en": "Monday"},
  "cp.quick.0": {"res": "CalendarGooglePrebuilt:@array/quick_response_defaults:0", "hu": "Csak pár percet késik.", "de": "Bin einige Minuten verspätet", "fr": "Désolé, j'aurai quelques minutes de retard.", "es": "Llego un par de minutos tarde", "en": "Running just a couple of minutes late."},
  "cp.quick.1": {"res": "CalendarGooglePrebuilt:@array/quick_response_defaults:1", "hu": "Legyen ott körülbelül 10 perc alatt.", "de": "Bin in etwa 10 Minuten da", "fr": "Désolé, j'arrive dans 10 minutes environ.", "es": "Llegaré en unos diez minutos", "en": "Be there in about 10 minutes."},
  "cp.quick.2": {"res": "CalendarGooglePrebuilt:@array/quick_response_defaults:2", "hu": "Kezdjék el nélkülem.", "de": "Fangt ohne mich an", "fr": "Commencez sans moi.", "es": "Empezad sin mí", "en": "Go ahead and start without me."},
  "cp.quick.3": {"res": "CalendarGooglePrebuilt:@array/quick_response_defaults:3", "hu": "Sajnálom, nem érek oda. Kénytelenek leszünk átütemezni.", "de": "Schaffe es leider nicht. Neuen Termin ausmachen?", "fr": "Désolé, je ne peux pas venir. Nous allons devoir reporter.", "es": "No puedo, mejor en otro momento", "en": "Sorry, I can't make it. We'll have to reschedule."}
