  "hp.Status off": {"res": "Hangouts:rich_status_off_summary", "hu": "Tudasd minden Hangouts-ismerősöddel, mire készülsz", "de": "Teilen Sie Ihren Status mit allen Ihren Hangouts-Kontakten.", "fr": "Indiquez ce que vous faites actuellement à toutes les personnes qui utilisent Hangouts avec vous.", "es": "Comparte lo que haces con tus contactos de Hangouts", "en": "Let everyone you use Hangouts with know what you're up to"},
  "hp.Status on": {"res": "Hangouts:rich_status_summary", "hu": "Az állapotodat mindenki látja, akivel a Hangouts szolgáltatást használod", "de": "Ihr Status ist für alle Ihre Hangout-Kontakte sichtbar.", "fr": "Toutes les personnes avec lesquelles vous participez à des Hangouts peuvent voir les informations relatives à votre disponibilité.", "es": "Tu estado es visible para todos los usuarios con los que utilices Hangouts", "en": "Your status is visible to everyone you use Hangouts with"},
  "hp.Device Presence": {"res": "Hangouts:share_device_presence_title", "hu": "Eszközjelenlét", "de": "Gerätepräsenz", "fr": "Présence sur l'appareil", "es": "Presencia del dispositivo", "en": "Device Presence"},
  "hp.Presence on": {"res": "Hangouts:share_device_presence_enabled_summary", "hu": "Mindenki, akivel a Hangouts szolgáltatást használod, tudni fogja, amikor aktív vagy az adott eszközön", "de": "Jeder Nutzer, mit dem Sie Hangouts verwenden, kann sehen, ob Sie auf diesem Gerät aktiv sind.", "fr": "Les personnes avec qui vous utilisez Hangouts savent lorsque vous êtes actif sur cet appareil.", "es": "Todos los usuarios con los que usas Hangouts saben cuándo estás activo en este dispositivo", "en": "Everyone you use Hangouts with knows when you are active on this device"},
  "hp.Presence off": {"res": "Hangouts:share_device_presence_disabled_summary", "hu": "Megoszthatod a „tevékenység az eszközön” állapotot az összes olyan személlyel, akivel használod a Hangouts szolgáltatást", "de": "Sie können Aktivitäten auf diesem Gerät mit jedem anderen Nutzer teilen, mit dem Sie Hangouts verwenden.", "fr": "Vous pouvez partager les données relatives à votre activité sur cet appareil avec toutes les personnes avec qui vous utilisez Hangouts.", "es": "Puedes compartir la actividad de este dispositivo con todos los usuarios con los que usas Hangouts", "en": "You can share activity on this device with everyone you use Hangouts with"},
