  "hp.Rename": {"res": "Hangouts:conversation_rename_option", "hu": "Átnevezés", "de": "Umbenennen", "fr": "Renommer", "es": "Cambiar nombre", "en": "Rename"},
  "hp.Rename Hangout": {"res": "Hangouts:realtimechat_conversation_rename_dialog_title", "hu": "Hangout átnevezése", "de": "Hangout umbenennen", "fr": "Renommer le Hangout", "es": "Cambia el nombre de la conversación", "en": "Rename Hangout"},
  "hp.Conversation notifications": {"res": "Hangouts:conversation_notifications_option", "hu": "Értesítések", "de": "Benachrichtigungen", "fr": "Notifications", "es": "Notificaciones", "en": "Notifications"},
  "hp.Chat message sound": {"res": "Hangouts:hangouts_message_notification_sound_title", "hu": "Csevegőüzenet hangja", "de": "Ton für Chatnachricht", "fr": "Son pour les messages instantanés", "es": "Sonido de mensaje de chat", "en": "Chat message sound"},
  "hp.Call ringtone": {"res": "Hangouts:hangouts_call_ringtone_title", "hu": "Csengőhang", "de": "Klingelton für Anruf", "fr": "Sonnerie pour les appels", "es": "Tono de llamada", "en": "Call ringtone"},
  "hp.Block %s": {"res": "Hangouts:conversation_block_option", "hu": "A(z) %s letiltása", "de": "%s blockieren", "fr": "Bloquer %s", "es": "Bloquear a %s", "en": "Block %s"},
  "hp.Unblock %s": {"res": "Hangouts:conversation_unblock_option", "hu": "A(z) %s tiltásának feloldása", "de": "%s nicht mehr blockieren", "fr": "Débloquer %s", "es": "Desbloquear a %s", "en": "Unblock %s"},
  "hp.Block title": {"res": "Hangouts:realtimechat_block_user_title", "hu": "A(z) %s letiltása", "de": "%s blockieren", "fr": "Bloquer %s", "es": "Bloquear a %s", "en": "Block %s"},
  "hp.Block text": {"res": "Hangouts:realtimechat_block_user_text", "hu": "Ha letiltod, közvetlen üzeneteket és értesítéseket nem fogsz kapni tőle, de az esetleges közös csoportos Hangouts-beszélgetéseitekben ez a személy továbbra is jelen lesz. <a href=\"http://support.google.com/hangouts?p=blocking\">További információ</a>", "de": "Blockierte Personen können Ihnen keine direkten Nachrichten und Benachrichtigungen mehr senden, sie nehmen jedoch weiterhin an gemeinsamen Gruppen-Hangouts teil. <a href=\"http://support.google.com/hangouts?p=blocking\">Weitere Informationen</a>", "fr": "Si vous bloquez cet utilisateur, vous ne recevrez plus de messages ni de notifications de sa part. En revanche, il sera toujours présent dans les Hangouts de groupe que vous avez en commun. <a href=\"http://support.google.com/hangouts?p=blocking\">En savoir plus</a>", "es": "Si bloqueas a esta persona, dejarás de recibir notificaciones y mensajes de ella, pero seguirá participando en las conversaciones de grupo que tengáis en común. <a href=\"http://support.google.com/hangouts?p=blocking\">Más información</a>", "en": "If blocked, you will no longer receive direct messages and notifications, but this person will still be present in any group Hangouts you have in common. <a href=\"http://support.google.com/hangouts?p=blocking\">Learn more</a>"},
  "hp.Block button": {"res": "Hangouts:realtimechat_block_user_button", "hu": "Letiltás", "de": "Blockieren", "fr": "Bloquer", "es": "Bloquear", "en": "Block"},
  "hp.Unblocked %s": {"res": "Hangouts:realtimechat_unblock_user_toast", "hu": "%s tiltása feloldva", "de": "%s ist nicht mehr blockiert.", "fr": "Vous avez bien débloqué %s.", "es": "Se ha desbloqueado a %s", "en": "Unblocked %s"},
  "hp.Leave": {"res": "Hangouts:realtimechat_conversation_leave_menu_item_text", "hu": "Kilépés", "de": "Verlassen", "fr": "Quitter", "es": "Salir", "en": "Leave"},
  "hp.Leave Hangout": {"res": "Hangouts:realtimechat_leave_conversation_title", "hu": "Hangout elhagyása", "de": "Hangout verlassen", "fr": "Quitter le Hangout", "es": "Abandonar conversación", "en": "Leave Hangout"},
  "hp.Leave text": {"res": "Hangouts:realtimechat_leave_conversation_text", "hu": "Ha kilépsz, nem tudod majd a csoporttagok üzeneteit elolvasni, és nem tudsz üzenetet küldeni nekik. Szeretnél kilépni a Hangouts-beszélgetésből?", "de": "Wenn Sie den Hangout verlassen, können Sie keine Nachrichten mehr lesen oder an die Gruppe senden. Möchten Sie den Hangout verlassen?", "fr": "Si vous quittez le Hangout, vous ne pourrez plus lire ni envoyer de messages à ce groupe. Voulez-vous vraiment le quitter ?", "es": "Si abandonas la conversación, no podrás leer ni enviar mensajes a este grupo. ¿Quieres abandonarla?", "en": "If you leave, you will no longer be able to read or send messages to this group. Do you want to leave this Hangout?"},
  "hp.Leave button": {"res": "Hangouts:realtimechat_leave_conversation_button_text", "hu": "Kilépés", "de": "Verlassen", "fr": "Quitter", "es": "Salir", "en": "Leave"},
  "hp.Stay": {"res": "Hangouts:realtimechat_stay_conversation_button_text", "hu": "Maradok", "de": "Bleiben", "fr": "Rester", "es": "Quedarme", "en": "Stay"},
